UPDATE /* LGSYSC00050.updateMyInfomationData */
       LGCOM_USER_M
   SET language_code                = #{languageCode}
     , system_code                  = #{systemCode}

     , default_org_id               = #{defaultOrgId}
     , default_org_id_use_flag      = #{defaultOrgIdUseFlag}

     , screen_design_theme_id       = #{screenDesignThemeId}
     , menu_use_flag                = #{menuUseFlag}
     , last_updated_by              = #{applicationUserId}
     , last_update_date             = SYSDATE
 WHERE application_user_id          = #{applicationUserId}

UPDATE /* LGSYSC00050.updateMyInfomationRegionUseData */
       LGCOM_USER_M
   SET request_region_code_use_flag = #{requestRegionCodeUseFlag}
     , last_updated_by              = #{USER_SESSION.applicationUserId}
     , last_update_date             = SYSDATE
 WHERE mail_addr = #{mailAddr}

mapper.select:
SELECT /* LGSYSC00050.retrieveMyAuthorityList */ application_user_id AS user_id , system_name , module_name , role_code , role_name FROM LGCOM_USER_ROLE_N_V WHERE application_user_id = #{USER_SESSION.applicationUserId} AND (apply_start_date IS NULL OR apply_start_date <= TRUNC(SYSDATE)) AND (apply_end_date IS NULL OR apply_end_date >= TRUNC(SYSDATE))
AND system_code = #{systemCode}
ORDER BY system_code, module_code, role_code
